@router.get("/api/v1/workspaces/{workspace_id}/activity-stream")
async def stream_workspace_activity(
    workspace_id: str,
    redis: Redis = Depends(get_redis),
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    membership = await db.execute(
        select(WorkspaceMember).where(
            WorkspaceMember.workspace_id == workspace_id,
            WorkspaceMember.user_id == current_user.id
        )
    )
    if not membership.scalar_one_or_none():
        raise HTTPException(status_code=403, detail="Access to workspace stream forbidden")

    async def event_generator():
        pubsub = redis.pubsub()
        await pubsub.subscribe(f"workspace_events:{workspace_id}")
        try:
            async for msg in pubsub.listen():
                if msg["type"] == "message":
                    yield {"event": "activity", "data": msg["data"].decode("utf-8")}
        finally:
            await pubsub.unsubscribe(f"workspace_events:{workspace_id}")

    return EventSourceResponse(event_generator())
